package policy

import (
	"fmt"
	"strings"
	"time"

	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// API constants. Policy documents are plain Kubernetes-style YAML so that they
// can live next to other cluster configuration and be reviewed like code.
const (
	APIVersion     = "guard.example.com/v1alpha1"
	KindPolicy     = "SecurityPolicy"
	KindTrustStore = "TrustStore"

	// EnforcementLabel is read from Namespace objects. The webhook
	// configurations generated by webhookconfig use it as a namespaceSelector
	// to decide which namespaces fail closed (strict) and which fail open
	// (standard, or the default when the label is absent).
	EnforcementLabel = "guard.example.com/enforcement"

	EnforcementStrict   = "strict"
	EnforcementStandard = "standard"
	EnforcementDisabled = "disabled"

	// DefaultTeamLabel maps a namespace to one or more owning teams. The value
	// is a comma-separated list of team names, so a shared namespace can be
	// jointly owned.
	DefaultTeamLabel = "guard.example.com/team"
)

// Mode controls whether a policy denies unsafe workloads or only reports them.
type Mode string

const (
	ModeEnforce Mode = "enforce"
	ModeAudit   Mode = "audit"
)

// FailureMode decides what happens when policy evaluation itself fails.
// closed is the safe default for carefully managed namespaces; open keeps
// unrelated deployments working during a policy/service fault.
type FailureMode string

const (
	FailureClosed FailureMode = "closed"
	FailureOpen   FailureMode = "open"
)

// Severity of a finding.
type Severity string

const (
	SeverityCritical Severity = "critical"
	SeverityHigh     Severity = "high"
	SeverityMedium   Severity = "medium"
	SeverityLow      Severity = "low"
	SeverityInfo     Severity = "info"
)

func (s Severity) Valid() bool {
	switch s {
	case SeverityCritical, SeverityHigh, SeverityMedium, SeverityLow, SeverityInfo:
		return true
	}
	return false
}

// Action is what a rule does when it finds an unsafe configuration.
type Action string

const (
	// ActionDeny rejects the request.
	ActionDeny Action = "deny"
	// ActionRemediate rewrites the object with a safe value and admits it.
	ActionRemediate Action = "remediate"
	// ActionAudit admits the object and records a finding (no warning noise).
	ActionAudit Action = "audit"
	// ActionWarn admits the object and surfaces an admission warning.
	ActionWarn Action = "warn"
)

func (a Action) Valid() bool {
	switch a {
	case ActionDeny, ActionRemediate, ActionAudit, ActionWarn:
		return true
	}
	return false
}

// Disposition is the outcome a finding reached for this request.
type Disposition string

const (
	DispositionDenied     Disposition = "denied"
	DispositionRemediated Disposition = "remediated"
	DispositionExempted   Disposition = "exempted"
	DispositionAudited    Disposition = "audited"
	DispositionWarned     Disposition = "warned"
	// DispositionPreExisting marks a violation that was already present on the
	// stored object; it is reported but does not block unrelated updates.
	DispositionPreExisting Disposition = "pre-existing"
)

// Finding is one policy violation or remediation.
type Finding struct {
	Policy      string      `json:"policy"`
	Rule        string      `json:"rule"`
	Severity    Severity    `json:"severity"`
	Action      Action      `json:"action"`
	Disposition Disposition `json:"disposition"`
	Path        string      `json:"path,omitempty"`
	Container   string      `json:"container,omitempty"`
	Message     string      `json:"message"`
	Fix         string      `json:"fix,omitempty"`
	Exemption   string      `json:"exemption,omitempty"`
	// ExemptionPolicy names the policy that declared the honoured exemption when
	// it came from another policy via spec.acceptExemptions.
	ExemptionPolicy string `json:"exemptionPolicy,omitempty"`
	// Advisory findings are informational: they describe what was done (for
	// example "an unknown kind was evaluated by structural scan") and can never
	// deny or rewrite an object.
	Advisory bool `json:"advisory,omitempty"`
	// ExemptionExpiresAt is set when an exemption was honoured so operators can
	// see when the risk re-appears.
	ExemptionExpiresAt *time.Time `json:"exemptionExpiresAt,omitempty"`
}

// Key identifies a finding independent of its message so that pre-existing
// violations can be matched between the old and new object.
func (f Finding) Key() string {
	return strings.Join([]string{f.Policy, f.Rule, f.Path, f.Container}, "|")
}

// ObjectMeta is the subset of metadata policies care about. Namespace is
// recorded for cluster-sourced policies so audit records can point at the
// object's origin; file-sourced policies leave it empty.
type ObjectMeta struct {
	Name        string            `json:"name"`
	Namespace   string            `json:"namespace,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
	Annotations map[string]string `json:"annotations,omitempty"`
}

// Policy is one SecurityPolicy document.
type Policy struct {
	APIVersion string     `json:"apiVersion"`
	Kind       string     `json:"kind"`
	Metadata   ObjectMeta `json:"metadata"`
	Spec       PolicySpec `json:"spec"`
}

// PolicySpec configures rules, scope and time-limited exemptions.
type PolicySpec struct {
	Description string `json:"description,omitempty"`
	// Mode defaults to enforce.
	Mode Mode `json:"mode,omitempty"`
	// FailureMode defaults to closed. This is the engine's decision when a rule
	// panics or cannot be evaluated; webhook availability is handled separately
	// by failurePolicy on the webhook configuration.
	FailureMode FailureMode `json:"failureMode,omitempty"`
	// TeamLabel overrides which namespace label maps to teams.
	TeamLabel string `json:"teamLabel,omitempty"`
	// MaxExemptionDuration caps how far in the future an exemption may expire.
	// Defaults to 720h (30 days).
	MaxExemptionDuration string      `json:"maxExemptionDuration,omitempty"`
	Scope                PolicyScope `json:"scope,omitempty"`
	Rules                []RuleSpec  `json:"rules"`
	Exemptions           []Exemption `json:"exemptions,omitempty"`
	// AcceptExemptions lists the IDs of exemptions defined by *other* policies
	// that this policy honours. Exemptions are declared where we intend to carry
	// the risk, but the dangerous setting may be caught by a different policy
	// bundle (a platform baseline vs. a team overlay). Naming the ID explicitly
	// makes the coupling reviewable, and the exemption still has to match this
	// policy's scope, rules and expiry to apply.
	AcceptExemptions []string `json:"acceptExemptions,omitempty"`
}

// PolicyScope limits which namespaces/teams a policy applies to. Empty lists
// mean "all"; exclusions always win.
type PolicyScope struct {
	Namespaces        []string              `json:"namespaces,omitempty"`
	ExcludeNamespaces []string              `json:"excludeNamespaces,omitempty"`
	Teams             []string              `json:"teams,omitempty"`
	ExcludeTeams      []string              `json:"excludeTeams,omitempty"`
	NamespaceSelector *metav1.LabelSelector `json:"namespaceSelector,omitempty"`
}

// RuleSpec enables and configures one rule.
type RuleSpec struct {
	ID       string         `json:"id"`
	Enabled  *bool          `json:"enabled,omitempty"`
	Action   Action         `json:"action,omitempty"`
	Severity Severity       `json:"severity,omitempty"`
	Config   map[string]any `json:"config,omitempty"`
}

// Exemption grants a time-limited exception for specific rules.
type Exemption struct {
	ID          string         `json:"id"`
	Reason      string         `json:"reason"`
	RequestedBy string         `json:"requestedBy"`
	Ticket      string         `json:"ticket,omitempty"`
	NotBefore   string         `json:"notBefore,omitempty"`
	ExpiresAt   string         `json:"expiresAt"`
	Scope       ExemptionScope `json:"scope"`
}

// ExemptionScope narrows an exemption. Rules must be listed explicitly or with
// the "*" wildcard; an exemption with no rule selector is rejected.
type ExemptionScope struct {
	Namespaces []string `json:"namespaces,omitempty"`
	Teams      []string `json:"teams,omitempty"`
	Workloads  []string `json:"workloads,omitempty"`
	Kinds      []string `json:"kinds,omitempty"`
	Rules      []string `json:"rules"`
}

// TrustStore lists image signatures trusted by the platform. It is intentionally
// separate from policies so security teams can rotate attestations without
// editing policy rules.
type TrustStore struct {
	APIVersion string         `json:"apiVersion"`
	Kind       string         `json:"kind"`
	Metadata   ObjectMeta     `json:"metadata"`
	Spec       TrustStoreSpec `json:"spec"`
}

// TrustStoreSpec holds trusted image attestations.
type TrustStoreSpec struct {
	// RequireSignature makes image-provenance deny images without a valid
	// attestation when the rule is enabled.
	Signatures []Signature `json:"signatures,omitempty"`
}

// Signature signs one image. Image may be a digest reference (preferred) or a
// tag reference; digest references are matched exactly.
type Signature struct {
	Image     string `json:"image"`
	Signer    string `json:"signer"`
	ExpiresAt string `json:"expiresAt,omitempty"`
}

// CompileError aggregates policy validation failures.
type CompileError struct {
	Problems []string
}

func (e *CompileError) Error() string {
	return "invalid policy: " + strings.Join(e.Problems, "; ")
}

// Add appends a problem.
func (e *CompileError) Add(format string, args ...any) {
	e.Problems = append(e.Problems, fmt.Sprintf(format, args...))
}
